const topics=base.topics.map(t=>{const r=byKey.get(t.key);return r?{...t,generalGuidanceMode:false,catalogOnly:false,specificGuidance:true,termResolution:false,sections:sectionsFor(r,'unknown'),refs:r.refs.map(s=>s.id),clinicalEntity:r.entity,termAssessment:r.assessment,directedReview:'2026-10-25'}:t;});
function resolve(v){const r=rowFor(v);if(r)return topics.find(t=>t.key===r.key);return inherited(()=>base.resolve(v));}
function build(input={}){const p=input&&typeof input==='object'?input:{},row=rowFor(p.diagnosis)||(()=>{const t=inherited(()=>base.resolve(p.diagnosis));return t&&byKey.get(t.key);})();if(!row)return inherited(()=>base.build(input));const age=p.age===undefined||p.age===null||p.age===''?'unknown':p.age;if(!Object.hasOwn(base.ages,age))return {ok:false,code:'AGE_INVALID',message:'Selecione uma faixa etária válida.'};const previous=inherited(()=>base.build({...p,diagnosis:row.key,age}));if(!previous?.ok)return previous;if(p.reviewed!==true&&p.danger!=='yes')return {ok:false,code:'REVIEW_REQUIRED',message:'Confirme a avaliação do diagnóstico pela equipe. O site não decide alta.'};const urgent=p.danger==='yes'||previous.mode==='urgent';let sections=sectionsFor(row,age);if(urgent)sections=[{title:'ATENDIMENTO URGENTE',items:['Há sinais de perigo informados. Procure atendimento imediato e não use esta ficha para adiar avaliação.']},...sections];const clean=(v,n)=>typeof v==='string'?v.replace(/[\u0000-\u001f\u007f]/g,' ').trim().slice(0,n):'',notes=clean(p.notes,1400),plan=clean(p.returnPlan,200);if(notes)sections.push({title:'COMPLEMENTO DA CONSULTA',items:[notes]});if(plan){const follow=sections.find(s=>s.title==='QUANDO REAVALIAR');if(follow)follow.items.push('Retorno combinado: '+plan);}const text='ORIENTAÇÕES AOS PAIS — '+row.label+'\nFaixa etária: '+base.ages[age]+'\n\n'+sections.map((s,i)=>(i+1)+'. '+s.title+'\n'+s.items.map(x=>'• '+x).join('\n')).join('\n\n');return {...previous,ok:true,mode:urgent?'urgent':'guidance',topic:row.key,label:row.label,sections,refs:row.refs.map(s=>s.id),text,warnings:urgent?['Avaliação prioritária necessária; esta ficha não autoriza alta.']:[],effectiveAgeBand:age,directedGuidance:true,termResolution:false,termAssessment:row.assessment};}
function audit(){const old=inherited(()=>base.audit()),issues=[...(old.issues||[])];for(const r of records){const t=topics.find(x=>x.key===r.key);if(!t||t.label!==r.label||t.specificGuidance!==true||t.termResolution!==false||!r.refs.every(s=>sources[s.id]))issues.push('parallel-batch-224-selected:'+r.key);}return {...old,ok:!issues.length,issues,topics:topics.length};}
